//! harbor: order helpers.

pub mod retry;

/// Total of an order in cents.
pub fn order_total(prices: &[u64], quantities: &[u32]) -> u64 {
    prices
        .iter()
        .zip(quantities)
        .map(|(price, qty)| price * u64::from(*qty))
        .sum()
}

use std::env;

fn main() {
    let args: Vec<String> = env::args().skip(1).collect();
    let total = harbor::order_total(&[1200, 450], &[2, 1]);
    println!("order total: {} cents", total);
    if args.iter().any(|a| a == "--help") {
        println!("usage: harbor [--help]");
    }
}

use std::time::{Duration, Instant};

/// Wait before the next attempt, doubling each time.
pub fn retry_backoff(attempt: u32) -> Duration {
    Duration::from_millis(100 << attempt.min(6))
}

/// True while the retry window is still open.
pub fn window_open(started: Instant, budget: Duration) -> bool {
    let now = Instant::now();
    now.duration_since(started) < budget
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn window_is_open_at_start() {
        let started = Instant::now();
        assert!(window_open(started, Duration::from_millis(1)));
    }
}

export interface Config {
  host: string;
  port: number;
}

// Read the service config from the environment.
export function loadConfig(env: Record<string, string | undefined>): Config {
  const host = env.HARBOR_HOST ?? "127.0.0.1";
  const port = Number(env.HARBOR_PORT ?? "8080");
  return { host, port };
}
